<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
if(PHP_SAPI!=='cli')exit(1);
$root=dirname(__DIR__);$backup=$root.'/storage/private/backups';if(!is_dir($backup))mkdir($backup,0700,true);
try{
 $dev=require $root.'/config/local.php';$demo=require $root.'/config/demo.php';$sources=['dev'=>$dev,'demo'=>$demo];$stamp=date('Ymd_His');$meta=[];
 foreach($sources as $label=>$cfg){$db=Hls\Database::connect($cfg);$tables=$db->query('SHOW FULL TABLES WHERE Table_type="BASE TABLE"')->fetchAll(PDO::FETCH_NUM);$path="$backup/{$stamp}_{$label}.sql";$fh=fopen($path,'wb');if(!$fh)throw new RuntimeException('Backup gagal dibuka.');fwrite($fh,"-- HLS backup {$label} {$stamp}\nSET FOREIGN_KEY_CHECKS=0;\n");$counts=[];foreach($tables as [$t]){$create=$db->query('SHOW CREATE TABLE `'.$t.'`')->fetch(PDO::FETCH_NUM)[1];fwrite($fh,"DROP TABLE IF EXISTS `{$t}`;\n{$create};\n");$rows=$db->query('SELECT * FROM `'.$t.'`')->fetchAll(PDO::FETCH_ASSOC);$counts[$t]=count($rows);foreach($rows as $row){$vals=[];foreach($row as $v)$vals[]=$v===null?'NULL':$db->quote((string)$v);fwrite($fh,'INSERT INTO `'.$t.'` (`'.implode('`,`',array_keys($row)).'`) VALUES ('.implode(',',$vals).');'."\n");}}fwrite($fh,"SET FOREIGN_KEY_CHECKS=1;\n");fclose($fh);$hash=hash_file('sha256',$path);$verify=file_get_contents($path);if(!$verify||substr_count($verify,'CREATE TABLE')!==count($tables))throw new RuntimeException("Backup {$label} verifikasi struktur gagal.");$meta[$label]=['database'=>$cfg['database'],'file'=>$path,'bytes'=>filesize($path),'sha256'=>$hash,'tables'=>count($tables),'rows'=>$counts];}
 $admin=new PDO('mysql:host=127.0.0.1;port=3306;charset=utf8mb4',getenv('HLS_DB_ADMIN_USER')?:'root',getenv('HLS_DB_ADMIN_PASSWORD')?:'', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$exists=(int)$admin->query("SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='hls_v2'")->fetchColumn();if(!$exists)$admin->exec('CREATE DATABASE hls_v2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');else{$n=(int)$admin->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='hls_v2'")->fetchColumn();if($n)throw new RuntimeException('hls_v2 sudah berisi tabel; konsolidasi dihentikan.');}$mainPass=(string)$dev['password'];$admin->exec("GRANT SELECT,INSERT,UPDATE,DELETE,CREATE,ALTER,INDEX,REFERENCES ON hls_v2.* TO 'hls_v2_app'@'127.0.0.1'");
 $src=Hls\Database::connect($demo);$dst=new PDO('mysql:host=127.0.0.1;dbname=hls_v2;charset=utf8mb4','hls_v2_app',$mainPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$dst->exec('SET FOREIGN_KEY_CHECKS=0');$tables=$src->query('SHOW FULL TABLES WHERE Table_type="BASE TABLE"')->fetchAll(PDO::FETCH_NUM);foreach($tables as [$t]){$create=$src->query('SHOW CREATE TABLE `'.$t.'`')->fetch(PDO::FETCH_NUM)[1];$dst->exec($create);$rows=$src->query('SELECT * FROM `'.$t.'`')->fetchAll(PDO::FETCH_ASSOC);if($rows){$cols=array_keys($rows[0]);$sql='INSERT INTO `'.$t.'` (`'.implode('`,`',$cols).'`) VALUES ('.implode(',',array_fill(0,count($cols),'?')).')';$ins=$dst->prepare($sql);foreach($rows as $row)$ins->execute(array_values($row));}}$dst->exec('SET FOREIGN_KEY_CHECKS=1');$target=['database'=>'hls_v2','username'=>'hls_v2_app','password'=>$mainPass,'base_path'=>'/hls-v2/public','secure_cookie'=>false,'idle_timeout'=>1800];file_put_contents($root.'/config/main.php',"<?php\nreturn ".var_export($target,true).";\n",LOCK_EX);$meta['target']=$target;$meta['created_at']=date(DATE_ATOM);file_put_contents($backup."/{$stamp}_consolidation.json",json_encode($meta,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);echo json_encode(['ok'=>true,'backup'=>$meta,'target'=>'hls_v2'],JSON_PRETTY_PRINT).PHP_EOL;
}catch(Throwable $e){fwrite(STDERR,'Konsolidasi gagal: '.$e->getMessage().PHP_EOL);exit(1);}
